// <auto-generated />

namespace SMAWinLoss.Summary
{
    using AutoMapper;
    using Fanex.Data.Repository;
    using Utilities.LinqDynamicSum;

    public interface WinLossService
    {
        Task<WinLossModel> GetSMAWinLoss(WinLossHttpParameter parameters);
    }

    public class WinLossServiceImp : WinLossService
    {
        private const int TurnoverIndex = 0;

        private const int IncomeIndex = 1;

        private const int MarginIndex = 2;

        private const int AveragePTIndex = 3;

        private const int AverageBetIndex = 4;

        private readonly IDynamicRepository repository;

        private readonly IMapper mapper;

        public WinLossServiceImp(IDynamicRepository repository, IMapper mapper)
        {
            this.repository = repository;
            this.mapper = mapper;
        }

        public async Task<WinLossModel> GetSMAWinLoss(WinLossHttpParameter parameters)
        {
            return await GetSMAWinLossFromDatabase(parameters);
        }

        private async Task<WinLossModel> GetSMAWinLossFromDatabase(WinLossHttpParameter parameters)
        {
            var result = new WinLossModel();
            var userNameWinLosses = new List<UsernameWinLoss>();
            var criteria = mapper.Map<WinLossCriteria>(parameters);
            var rawData = await repository.FetchMultipleAsync<WinLossEntity, WinLossEntity, int>(criteria);

            var usernameGroups = rawData.Item1.GroupBy(x => new { x.CustId, x.Username, x.Role, x.Currency, x.VirtualRate });

            foreach (var group in usernameGroups)
            {
                var usernameGroupRawData = rawData.Item1.Where(
                    x => x.CustId == group.Key.CustId
                    && x.Username == group.Key.Username
                    && x.Currency == group.Key.Currency);

                var userNameTotal = usernameGroupRawData.DynamicSum();

                var usernameData = InitUserData(group.Key.CustId, group.Key.Username, group.Key.Role, group.Key.Currency, group.Key.VirtualRate, parameters.Year);

                foreach (var monthlyRawDataByUsername in usernameGroupRawData)
                {
                    var date = $"{monthlyRawDataByUsername.RptDate:MMM, yyyy}";
                    usernameData[TurnoverIndex].Months.FirstOrDefault(x => x.Month == date).Value = monthlyRawDataByUsername.RealTurnover;
                    usernameData[IncomeIndex].Months.FirstOrDefault(x => x.Month == date).Value = monthlyRawDataByUsername.RealIncome;
                    usernameData[MarginIndex].Months.FirstOrDefault(x => x.Month == date).Value = monthlyRawDataByUsername.RealMargin;
                    usernameData[AveragePTIndex].Months.FirstOrDefault(x => x.Month == date).Value = monthlyRawDataByUsername.AvgPT;
                    usernameData[AverageBetIndex].Months.FirstOrDefault(x => x.Month == date).Value = monthlyRawDataByUsername.AvgBet;
                }

                usernameData[TurnoverIndex].Months.FirstOrDefault(x => x.Month == "Total").Value = userNameTotal.RealTurnover;
                usernameData[IncomeIndex].Months.FirstOrDefault(x => x.Month == "Total").Value = userNameTotal.RealIncome;
                usernameData[MarginIndex].Months.FirstOrDefault(x => x.Month == "Total").Value = userNameTotal.RealMargin;
                usernameData[AveragePTIndex].Months.FirstOrDefault(x => x.Month == "Total").Value = userNameTotal.AvgPT;
                usernameData[AverageBetIndex].Months.FirstOrDefault(x => x.Month == "Total").Value = userNameTotal.AvgBet;

                userNameWinLosses.AddRange(usernameData);
            }

            var total = SumTotal(parameters.Year, rawData.Item2);

            result.UsernameWinLosses = userNameWinLosses;
            result.Total = total;
            result.TotalItems = rawData.Item3.FirstOrDefault() * 5;

            return result;
        }

        private List<UsernameWinLoss> InitUserData(
            int custId,
            string username,
            string role,
            string currency,
            string virtualRate,
            int year)
        {
            var usernameTurnover = new UsernameWinLoss
            {
                CustId = custId,
                Username = username,
                Role = role,
                Currency = currency,
                Name = "Real Turnover",
                VirtualRate = virtualRate,
                Months = InitMonthlyValue(year)
            };
            var usernameIncome = new UsernameWinLoss
            {
                CustId = custId,
                Username = username,
                Role = role,
                Currency = currency,
                Name = "Real Income",
                VirtualRate = virtualRate,
                Months = InitMonthlyValue(year)
            };
            var usernameMargin = new UsernameWinLoss
            {
                CustId = custId,
                Username = username,
                Role = role,
                Currency = currency,
                Name = "Real Margin (%)",
                VirtualRate = virtualRate,
                Months = InitMonthlyValue(year)
            };
            var usernameAvgPT = new UsernameWinLoss
            {
                CustId = custId,
                Username = username,
                Role = role,
                Currency = currency,
                Name = "Average PT (%)",
                VirtualRate = virtualRate,
                Months = InitMonthlyValue(year)
            };
            var usernameAvgBet = new UsernameWinLoss
            {
                CustId = custId,
                Username = username,
                Role = role,
                Currency = currency,
                Name = "Average Bet",
                VirtualRate = virtualRate,
                Months = InitMonthlyValue(year)
            };

            return new List<UsernameWinLoss>
            {
                usernameTurnover,
                usernameIncome,
                usernameMargin,
                usernameAvgPT,
                usernameAvgBet
            };
        }

        private List<UsernameWinLoss> SumTotal(int year, IEnumerable<WinLossEntity> rawData)
        {
            var result = new List<UsernameWinLoss>();

            var totalTurnover = new UsernameWinLoss
            {
                Username = "Total",
                Name = "Real Turnover",
                Months = InitMonthlyValue(year)
            };

            var totalIncome = new UsernameWinLoss
            {
                Username = "Total",
                Name = "Real Income",
                Months = InitMonthlyValue(year)
            };

            var totalMargin = new UsernameWinLoss
            {
                Username = "Total",
                Name = "Real Margin (%)",
                Months = InitMonthlyValue(year)
            };

            var totalByMonth = SumTotalByMonth(rawData);

            foreach (var item in totalByMonth)
            {
                var date = $"{item.RptDate:MMM, yyyy}";
                totalTurnover.Months.FirstOrDefault(x => x.Month == date).Value = item.RealTurnover;
                totalIncome.Months.FirstOrDefault(x => x.Month == date).Value = item.RealIncome;
                totalMargin.Months.FirstOrDefault(x => x.Month == date).Value = item.RealMargin;
            }

            var allTotal = SumAllTotal(rawData);
            totalTurnover.Months.FirstOrDefault(x => x.Month == "Total").Value = allTotal.RealTurnover;
            totalIncome.Months.FirstOrDefault(x => x.Month == "Total").Value = allTotal.RealIncome;
            totalMargin.Months.FirstOrDefault(x => x.Month == "Total").Value = allTotal.RealMargin;

            result.AddRange(new List<UsernameWinLoss> { totalTurnover, totalIncome, totalMargin });

            return result;
        }

        private List<WinLossEntity> SumTotalByMonth(IEnumerable<WinLossEntity> rawData)
        {
            var result = new List<WinLossEntity>();

            var monthGroups = rawData.GroupBy(x => x.RptDate);

            foreach (var monthGroup in monthGroups)
            {
                var monthRawData = rawData.Where(x => x.RptDate == monthGroup.Key);
                var sumMonthlyWinLoss = monthRawData.DynamicSum();

                result.Add(sumMonthlyWinLoss);
            }

            return result;
        }

        private WinLossEntity SumAllTotal(IEnumerable<WinLossEntity> rawData)
        {
            return rawData.DynamicSum();
        }

        private List<MonthModel> InitMonthlyValue(int year)
        {
            var result = new List<MonthModel>();

            for (var i = 0; i < 12; i++)
            {
                result.Add(new MonthModel
                {
                    Month = $"{new DateTime(year, i + 1, 1):MMM, yyyy}"
                });
            }

            result.Add(new MonthModel
            {
                Month = "Total"
            });

            return result;
        }
    }
}